import{_ as a,c as t,o as i,ae as o}from"./chunks/framework.Bi6zybwU.js";const b=JSON.parse('{"title":"Image/File/Lightbox","description":"Image/File/Lightbox","frontmatter":{"title":"Image/File/Lightbox","description":"Image/File/Lightbox"},"headers":[],"relativePath":"guide/field-types/image-file-lightbox.md","filePath":"guide/field-types/image-file-lightbox.md"}'),n={name:"guide/field-types/image-file-lightbox.md"};function l(h,e,g,r,s,d){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="image-file-lightbox" tabindex="-1">Image/File/Lightbox <a class="header-anchor" href="#image-file-lightbox" aria-label="Permalink to &quot;Image/File/Lightbox&quot;">​</a></h1><p>A data table is only engaging when it has multimedia and not just plain text. This is why the Image/File/Lightbox data type is used for columns with images, videos, GIFs, icons, etc. in Ninja Tables. And a lightbox is for when the image or the media needs to appear much clearer and bigger. When you click an image that has a lightbox format, it will open with a dark background. You can decide the data type right from the start when you add a column to the table. From your dashboard, go to the Ninja Tables plugin → Tables (the table where you want to add Column) → Add Column.</p><h2 id="lightbox-field-in-ninja-tables" tabindex="-1">Lightbox Field in Ninja Tables <a class="header-anchor" href="#lightbox-field-in-ninja-tables" aria-label="Permalink to &quot;Lightbox Field in Ninja Tables&quot;">​</a></h2><p>This data type allows you to add images, GIFs, videos, or YouTube links in a table column.</p><ul><li>Go to the <strong>Data Type</strong> option and select the <strong>Image/File/Lightbox</strong> type of the column and add a column. <img src="https://ninjatables.com/wp-content/uploads/2023/09/media-lightbox-1024x527.png" alt="media lightbox"></li><li>Now a new column with data type as lightbox has been added to the table.</li></ul><h3 id="image-linkable" tabindex="-1"><strong>Image Linkable</strong> <a class="header-anchor" href="#image-linkable" aria-label="Permalink to &quot;**Image Linkable**&quot;">​</a></h3><p>An <strong>Image Linkable</strong> option automatically appears after selecting the Image/File/Lightbox field. This option includes <strong>Image Only,</strong> <strong>Image Lightbox</strong>, **Iframe Lightbox **&amp; <strong>Link to URL</strong>. Lightbox is a Pro feature</p><h4 id="image-only" tabindex="-1"><strong>Image Only</strong> <a class="header-anchor" href="#image-only" aria-label="Permalink to &quot;**Image Only**&quot;">​</a></h4><p>Only image files can be added to the column’s field in this option. Both JPG &amp; PNG file formats are supported. This format won&#39;t open the image in a lightbox.</p><h4 id="image-lightbox" tabindex="-1"><strong>Image Lightbox</strong> <a class="header-anchor" href="#image-lightbox" aria-label="Permalink to &quot;**Image Lightbox**&quot;">​</a></h4><p>When an image is uploaded using this option, the image is displayed in a pop-up form when it is clicked. The background will appear darker to make the image look clear. If you choose** Image Lightbox**, the output of this field will look like this after clicking the image from the table - <img src="https://ninjatables.com/wp-content/uploads/2023/08/Image-Lightbox.png" alt="Image-Lightbox"></p><h4 id="iframe-lightbox" tabindex="-1"><strong>Iframe Lightbox</strong> <a class="header-anchor" href="#iframe-lightbox" aria-label="Permalink to &quot;**Iframe Lightbox**&quot;">​</a></h4><p>Here the image can be added along with the iframe URL. To select the image as an Iframe Lightbox, upload an image with an Iframe URL like the example below - When an image is clicked on the front end, the targeted URL will be shown as a pop-up. Let&#39;s see the output of how it works - <img src="https://ninjatables.com/wp-content/uploads/2023/08/Image-iframe.png" alt="Image-iframe"></p><h4 id="link-to-url" tabindex="-1"><strong>Link to URL</strong> <a class="header-anchor" href="#link-to-url" aria-label="Permalink to &quot;**Link to URL**&quot;">​</a></h4><p>To add a link to a URL in an image, click the Link to URL radio button and upload the image along with the target link. When an image is clicked on the front end, it is redirected to the <strong>targeted</strong> <strong>URL</strong>. The link can be opened in a new window. Here&#39;s how a table with Image Only and Iframe Lightbox looks like. [ninja_tables id=&quot;4693&quot;] Add an image with lightbox feature, use Iframe lightbox, or link a media in Ninja Tables easily.</p>',15)])])}const p=a(n,[["render",l]]);export{b as __pageData,p as default};
